const trialId = "resilient_webhook_idempotency__dztNL23";
const taskId = `webhook-handler-${trialId}`;

async function main() {
  const idempotencyKey = `payment-${Date.now()}`;
  const payload = { idempotencyKey, amount: 4200 };

  const run1 = await tasks.trigger<typeof webhookHandler>(taskId, payload, {
    idempotencyKey,
  });

  const run2 = await tasks.trigger<typeof webhookHandler>(taskId, payload, {
    idempotencyKey,
  });

  console.log(`Run ID 1: ${run1.id}, Run ID 2: ${run2.id}`);

  await runs.poll(run1.id);
  const runDetails = await runs.retrieve(run1.id);

  if (runDetails.output) {
    console.log("Run output:", runDetails.output);
  }
}

